tools.example:
load fisheriris
tree = fitctree(meas, species, 'MinLeafSize', 5, 'PredictorNames', ...
    {'SL','SW','PL','PW'});
view(tree, 'Mode', 'graph')
cv = crossval(tree, 'KFold', 10);
fprintf('CV error = %.3f\n', kfoldLoss(cv));

load ionosphere
rng(1)
Mdl = fitcsvm(X, Y, 'KernelFunction', 'rbf', 'KernelScale', 'auto', ...
    'Standardize', true, 'ClassNames', {'b','g'});
CVMdl = crossval(Mdl, 'KFold', 10);
fprintf('CV loss = %.3f\n', kfoldLoss(CVMdl));
ScoreMdl = fitPosterior(Mdl);

load fisheriris
t = templateSVM('KernelFunction', 'gaussian', 'Standardize', true);
Mdl = fitcecoc(meas, species, 'Learners', t, 'Coding', 'onevsone');
CV = crossval(Mdl, 'KFold', 5);
fprintf('CV error %.3f\n', kfoldLoss(CV));
C = confusionmat(species, resubPredict(Mdl));

load fisheriris
rng(0)
Mdl = fitcknn(meas, species, 'NumNeighbors', 5, ...
    'Distance', 'euclidean', 'DistanceWeight', 'inverse', 'Standardize', true);
cv = crossval(Mdl, 'KFold', 10);
fprintf('CV loss = %.3f\n', kfoldLoss(cv));

load fisheriris
Mdl = fitcnb(meas, species, 'DistributionNames', 'kernel');
[label, score] = predict(Mdl, meas(1:3,:));
fprintf('Resub loss = %.3f\n', resubLoss(Mdl));

load fisheriris
Mdl = fitcdiscr(meas, species, 'DiscrimType', 'quadratic');
fprintf('Resub error %.3f\n', resubLoss(Mdl));
[err, gamma, delta] = cvshrink(fitcdiscr(meas, species), 'NumGamma', 5);

load nlpdata
rng(1)
Mdl = fitclinear(X, Y, 'Learner', 'logistic', ...
    'Regularization', 'lasso', 'Solver', 'sparsa');
nnzCoefs = nnz(Mdl.Beta);
fprintf('%d of %d features used\n', nnzCoefs, numel(Mdl.Beta));

load carsmall
t = templateTree('MaxNumSplits', 8, 'Surrogate', 'on', 'Reproducible', true);
Mdl = fitrensemble([Weight Horsepower], MPG, 'Method', 'LSBoost', ...
    'Learners', t, 'NumLearningCycles', 150);

load fisheriris
rng(1)
[idx, C, sumd] = kmeans(zscore(meas), 3, 'Replicates', 10, 'Distance', 'sqeuclidean');
gscatter(meas(:,3), meas(:,4), idx)
hold on, plot(C(:,3), C(:,4), 'kx', 'MarkerSize', 12, 'LineWidth', 3)
fprintf('Total within-cluster distance: %.2f\n', sum(sumd));

rng(2)
X = [randn(100,2); randn(100,2)+4; randn(20,2)*8];
[idx, C, ~, ~, midx] = kmedoids(X, 3, 'Distance', 'cityblock', 'Replicates', 5);
gscatter(X(:,1), X(:,2), idx)
hold on, plot(X(midx,1), X(midx,2), 'ko', 'MarkerSize', 12)

rng(3)
th = rand(300,1)*2*pi;
X = [cos(th)+0.1*randn(300,1), sin(th)+0.1*randn(300,1); 0.15*randn(100,2)];
[idx, corepts] = dbscan(X, 0.25, 8);
gscatter(X(:,1), X(:,2), idx)
fprintf('%d clusters, %d noise points\n', max(idx), sum(idx == -1));

load fisheriris
D = pdist(zscore(meas), 'euclidean');
sq = squareform(D);
Z = linkage(D, 'ward');
fprintf('Cophenetic correlation: %.3f\n', cophenet(Z, D));

load fisheriris
X = zscore(meas);
Z = linkage(X, 'ward', 'euclidean');
figure, dendrogram(Z, 0, 'ColorThreshold', 'default')
idx = cluster(Z, 'MaxClust', 3);
crosstab(idx, species)

load fisheriris
Z = linkage(zscore(meas), 'average');
T3 = cluster(Z, 'MaxClust', 3);
Td = cluster(Z, 'Cutoff', 1.5, 'Criterion', 'distance');
fprintf('%d clusters by distance cutoff\n', max(Td));

load fisheriris
Z = linkage(zscore(meas), 'ward');
[H, T, perm] = dendrogram(Z, 20, 'ColorThreshold', 10, 'Orientation', 'left');
set(H, 'LineWidth', 1.2)

load fisheriris
rng(0)
eva = evalclusters(zscore(meas), 'kmeans', 'silhouette', 'KList', 1:6);
fprintf('Optimal K = %d\n', eva.OptimalK);
plot(eva)

load fisheriris
rng(1)
idx = kmeans(zscore(meas), 3, 'Replicates', 5);
[s, h] = silhouette(zscore(meas), idx, 'sqeuclidean');
fprintf('Mean silhouette = %.3f\n', mean(s));

load fisheriris
rng(1)
gm = fitgmdist(meas(:,3:4), 3, 'Replicates', 10, 'RegularizationValue', 1e-5);
idx = cluster(gm, meas(:,3:4));
P = posterior(gm, meas(:,3:4));
fprintf('AIC = %.1f, BIC = %.1f\n', gm.AIC, gm.BIC);
gscatter(meas(:,3), meas(:,4), idx)

load hald
[coeff, score, latent, tsq, explained] = pca(zscore(ingredients));
pareto(explained)
fprintf('First two PCs explain %.1f%%\n', sum(explained(1:2)));
biplot(coeff(:,1:2), 'Scores', score(:,1:2))

load fisheriris
rng(1)
[Y, loss] = tsne(meas, 'Perplexity', 20, 'Standardize', true, 'NumDimensions', 2);
gscatter(Y(:,1), Y(:,2), species)
fprintf('KL divergence = %.4f\n', loss);

load fisheriris
rng(0)
c = cvpartition(species, 'KFold', 5);
err = zeros(c.NumTestSets, 1);
for i = 1:c.NumTestSets
    tr = training(c, i); te = test(c, i);
    mdl = fitcknn(meas(tr,:), species(tr), 'NumNeighbors', 5);
    err(i) = mean(~strcmp(predict(mdl, meas(te,:)), species(te)));
end
fprintf('Mean CV error: %.3f\n', mean(err));

load carsmall
keep = ~any(isnan([Weight Horsepower MPG]), 2);
X = [Weight(keep) Horsepower(keep)]; y = MPG(keep);
mse = crossval('mse', X, y, 'Predfun', ...
    @(xtr, ytr, xte) predict(fitrtree(xtr, ytr), xte), 'KFold', 10);
fprintf('CV MSE = %.2f\n', mse);

load fisheriris
rng(0)
CVMdl = fitctree(meas, species, 'KFold', 10);
fprintf('Average CV error: %.3f\n', kfoldLoss(CVMdl));
perFold = kfoldLoss(CVMdl, 'Mode', 'individual');
fprintf('Std across folds: %.3f\n', std(perFold));

load ionosphere
rng(1)
cv = cvpartition(Y, 'HoldOut', 0.3);
Mdl = fitcensemble(X(training(cv),:), Y(training(cv)), 'Method', 'Bag');
testErr = loss(Mdl, X(test(cv),:), Y(test(cv)));
fprintf('Hold-out error: %.3f\n', testErr);

load fisheriris
rng(0)
Mdl = fitcdiscr(meas, species);
pred = resubPredict(Mdl);
[C, order] = confusionmat(species, pred);
precision = diag(C) ./ sum(C, 1)';
recall = diag(C) ./ sum(C, 2);
disp(table(order, precision, recall))

load fisheriris
Mdl = fitcecoc(meas, species);
pred = resubPredict(Mdl);
cm = confusionchart(species, pred, ...
    'RowSummary', 'row-normalized', 'ColumnSummary', 'column-normalized');
cm.Title = 'Iris classification';

load ionosphere
rng(0)
Mdl = fitclinear(X, Y, 'Learner', 'logistic');
[~, scores] = predict(Mdl, X);
[fpr, tpr, thr, auc, opt] = perfcurve(Y, scores(:,2), 'g');
plot(fpr, tpr, opt(1), opt(2), 'ro')
xlabel('FPR'), ylabel('TPR'), title(sprintf('AUC = %.3f', auc))

load ionosphere
[idx, w] = relieff(X, Y, 10);
bar(w(idx(1:15)))
xticklabels(string(idx(1:15)))
fprintf('Top 5 features: %s\n', mat2str(idx(1:5)));

load ionosphere
rng(0)
fun = @(xtr, ytr, xte, yte) ...
    sum(~strcmp(yte, predict(fitcdiscr(xtr, ytr, 'DiscrimType', 'pseudolinear'), xte)));
c = cvpartition(Y, 'KFold', 10);
[inmodel, hist] = sequentialfs(fun, X, Y, 'cv', c, 'options', statset('Display','iter'));
fprintf('%d features selected\n', sum(inmodel));

load carsmall
X = [Weight Horsepower Acceleration Displacement];
names = {'Weight','HP','Accel','Disp'};
Mdl = fitrensemble(X, MPG, 'Method', 'Bag');
imp = predictorImportance(Mdl);
bar(imp); xticklabels(names); ylabel('Importance')

load fisheriris
tbl = array2table(meas, 'VariableNames', {'SL','SW','PL','PW'});
tbl.Species = categorical(species);
classificationLearner(tbl, 'Species', 'KFold', 5)
